"""Ten original exposure-prevention questions."""
from qbank_authoring import question,ref,finalize
RW=ref('WHO: Rabies Vaccinations and Immunization','https://www.who.int/teams/control-of-neglected-tropical-diseases/rabies/vaccinations-and-immunization')
RC=ref('CDC: Rabies Post-exposure Prophylaxis Guidance, 2026','https://www.cdc.gov/rabies/hcp/clinical-care/post-exposure-prophylaxis.html')
HB=ref('CDC: Responding to HBV Exposures in Health Care','https://www.cdc.gov/hepatitis-b/hcp/infection-control/index.html')
HP=ref('CDC: Nonoccupational HIV PEP Recommendations, 2025','https://www.cdc.gov/mmwr/volumes/74/rr/rr7401a1.htm')
HC=ref('CDC: HCV Exposure Testing and Management for Health-Care Personnel','https://www.cdc.gov/mmwr/volumes/69/rr/rr6906a1.htm')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('What immediate action is central after a potentially rabid animal bite?', 'Thoroughly wash and flush the wound with soap and water for at least 15 minutes, then urgently assess indicated prophylaxis',[
 ('Apply a tight bandage without cleaning','This does not remove contaminated material.'),('Wait for symptoms before seeking prophylaxis','Once clinical rabies develops, prevention is generally too late.'),('Use antibiotics as a substitute for rabies vaccination','Antibacterials do not provide rabies immunity.')],
 'Mechanical wound cleaning is an active part of rabies prevention', '**Prompt washing reduces local viral contamination.**',['Use an appropriate antiseptic when available.','Assess tetanus protection and other wound needs separately.'], '**Determine exposure category and prior vaccination.**',['Use the current local vaccine/RIG or monoclonal-antibody pathway.','Do not let cleaning replace indicated biological prophylaxis.'],[['Immediate','Wash at least 15 minutes'],['Risk assessment','Category and vaccine history'],['Prevention','Indicated vaccine and passive antibody']],[RW])
q('An unvaccinated person sustains a category III transdermal bite from a rabies-risk animal. Which prophylaxis components are required under WHO principles?', 'Wound care, prompt rabies vaccine and indicated passive antibody infiltrated appropriately at the exposure site',[
 ('Vaccine alone automatically suffices for every category III exposure','Passive antibody is indicated in the previously unvaccinated category III setting.'),('Rabies immunoglobulin alone without vaccination','Passive protection does not replace active immunization.'),('Oral antibiotics alone','They do not prevent viral rabies.')],
 'Passive and active protection bridge different time periods', '**Local antibody neutralizes virus before vaccine immunity develops.**',['Rabies immunoglobulin or an approved monoclonal product is used according to local policy.','Wound infiltration and dose limits require correct technique.'], '**Use the recommended national schedule and complete it.**',['Route and vaccine schedule vary by approved pathway.','Avoid delaying indicated vaccine while seeking the passive product.'],[['Wound','Cleaning'],['Passive','Immediate local protection'],['Active','Vaccine-induced immunity']],[RW],style='clinical_scenario')
q('An immunocompetent adult with documented complete prior modern rabies vaccination has a new qualifying exposure. What is the usual CDC PEP approach?', 'Wound care and vaccine boosters on days 0 and 3, without HRIG',[
 ('HRIG alone with no vaccine boosters','That is not the previously vaccinated pathway.'),('The full unvaccinated regimen plus routine HRIG in every case','Prior complete vaccination changes management.'),('No assessment or treatment is needed because vaccination eliminates every future exposure decision','New exposures still require assessment and indicated boosters.')],
 'An immune priming history changes the post-exposure regimen', '**Previously vaccinated eligible patients receive a shorter booster course.**',['Confirm the prior course qualifies and is documented.','Immunocompromise or unusual vaccine histories require specialist review.'], '**Do not administer routine HRIG in this standard previously vaccinated pathway.**',['Provide correct wound care.','Use the current local policy if vaccination was nonstandard or uncertain.'],[['Prior complete vaccination','Verify documentation'],['Boosters','Days 0 and 3'],['HRIG','Not routine in this pathway']],[RC],style='clinical_scenario')
q('A person presents several days after a high-risk rabies exposure and remains asymptomatic. What is the best principle?', 'Urgently assess and provide indicated PEP rather than withhold it solely because the presentation was delayed',[
 ('PEP can never help after the day of the bite','Delay alone is not the universal exclusion criterion.'),('Wait for hydrophobia before vaccination','Clinical disease is not the time to begin prevention.'),('A healed wound proves the risk has disappeared','External healing does not establish absence of viral exposure.')],
 'Rabies prevention must precede clinical disease', '**Delayed presentation still needs urgent risk-based management.**',['Animal species, location, exposure type and observation/testing affect the decision.','Use public-health or rabies expertise for uncertainty.'], '**Begin the indicated pathway promptly.**',['Immunoglobulin timing is related to vaccine initiation and the specific protocol.','Do not improvise additional doses without assessing the actual history.'],[['Delayed but asymptomatic','Still assess for PEP'],['Clinical symptoms','Prevention window may have passed'],['Decision','Exposure-specific expert pathway']],[RC,RW])
q('A vaccinated health-care worker has documented anti-HBs ≥10 mIU/mL after a complete series and sustains an HBV-risk needlestick. What is usually needed for HBV PEP?', 'No HBV-specific prophylaxis based on the documented adequate response',[
 ('HBIG is mandatory after every exposure regardless of response','Documented immunity changes the need.'),('Restart the full series after every needlestick','This is not the routine responder pathway.'),('No reporting or assessment for any bloodborne infection is needed','HIV/HCV and wound/exposure assessment remain separate.')],
 'Documented response is more informative than a vaccine-history label alone', '**Anti-HBs ≥10 after a complete series documents protective response in the usual occupational pathway.**',['Maintain the relevant records.','Different pathways apply to nonresponders and incompletely vaccinated people.'], '**Still perform the overall occupational-exposure assessment.**',['Document the event and source information.','Evaluate other bloodborne pathogens as indicated.'],[['HBV responder','No routine HBV PEP'],['Documentation','Complete series plus adequate response'],['Other risks','Assess separately']],[HB],style='clinical_scenario')
q('An unvaccinated clinician sustains a needlestick from an HBsAg-positive source. Which HBV strategy is appropriate?', 'Prompt HBIG and initiation of the hepatitis B vaccine series at separate sites',[
 ('Vaccine alone always provides immediate sufficient protection','Passive antibody is also indicated in this setting.'),('HBIG alone provides permanent immunity','It is passive and temporary.'),('Wait until symptomatic hepatitis before any intervention','Prevention should be prompt.')],
 'A susceptible exposed person needs immediate and future protection', '**HBIG provides passive protection while vaccination induces active immunity.**',['Start promptly according to the occupational pathway.','Follow-up serology is timed to avoid misleading effects of recent passive antibody.'], '**Complete the vaccine series and record the response.**',['Nonresponder histories need a different protocol.','Assess HIV and HCV separately.'],[['Passive','HBIG'],['Active','Hepatitis B vaccine'],['Follow-up','Series completion and timed testing']],[HB],style='clinical_scenario')
q('A person presents 20 hours after a substantial nonoccupational HIV exposure. What is the recommended timing principle?', 'Start indicated PEP as soon as possible, ideally within 24 hours and no later than 72 hours, for 28 days',[
 ('Wait for every source and laboratory result before the first dose','This can delay time-sensitive prevention.'),('Use a single antiretroviral dose as a complete course','A complete 28-day regimen is recommended.'),('Begin routinely several weeks later with equal evidence of benefit','The recommended initiation window is much earlier.')],
 'HIV PEP is a time-sensitive prevention intervention', '**Risk assessment and the first dose should occur promptly.**',['Obtain baseline tests without delaying justified initiation.','Use an appropriate complete regimen.'], '**Arrange follow-up from the start.**',['Review adherence, adverse effects and testing.','Discuss transition to PrEP if ongoing exposure risk is present.'],[['Start','As soon as possible within 72 hours'],['Course','28 days'],['Follow-up','Testing and prevention planning']],[HP],style='clinical_scenario')
q('Which complete regimen is a preferred option for many adults/adolescents under CDC 2025 nonoccupational HIV PEP guidance?', 'Bictegravir/emtricitabine/tenofovir alafenamide',[
 ('Dolutegravir alone','Monotherapy is not the recommended PEP regimen.'),('Lamivudine alone','It is inadequate.'),('A seven-day course of zidovudine alone for every exposure','That is not the current preferred complete regimen.')],
 'PEP selection considers potency, tolerability and completion', '**The 2025 CDC update includes BIC/FTC/TAF among preferred regimens.**',['A dolutegravir plus appropriate tenofovir and FTC/3TC combination is another preferred approach.','Renal function, HBV, pregnancy and interactions guide individual selection.'], '**Do not confuse treatment simplification with PEP evidence.**',['Use the full prescribed course.','Review access and tolerability early.'],[['Option','BIC/FTC/TAF'],['Alternative preferred approach','DTG plus appropriate two-drug backbone'],['Selection','Patient-specific assessment']],[HP])
q('A baseline HIV test is negative immediately after an exposure for which PEP is indicated. What does that result mean?', 'It does not exclude infection from the very recent exposure, so indicated PEP and scheduled follow-up testing remain necessary',[
 ('It proves the exposure could not transmit HIV','The diagnostic window has not elapsed.'),('It eliminates every need for follow-up','Follow-up testing is part of the pathway.'),('It confirms that the source person is HIV-negative','The exposed person’s test does not determine source status.')],
 'A baseline result and an exposure-outcome result answer different questions', '**Baseline testing assesses pre-existing detectable infection.**',['Very recent acquisition can be in the window period.','Antiretroviral use can affect follow-up interpretation.'], '**Use the recommended follow-up testing schedule.**',['Assess acute symptoms and adherence.','Do not delay the first dose while waiting for a laboratory result when PEP is justified.'],[['Baseline','Pre-existing detectable infection'],['Recent event','May be too early to detect'],['Follow-up','Confirms outcome through the recommended pathway']],[HP])
q('After an occupational exposure to HCV-positive blood, which prevention/testing strategy is recommended?', 'No routine antiviral PEP; perform baseline and indicated follow-up testing, including early HCV RNA, and treat infection if detected',[
 ('HBIG prevents HCV infection','It does not.'),('A routine short DAA course is recommended for every exposure','CDC does not recommend routine HCV PEP.'),('Wait for antibody positivity only, with no role for RNA','RNA can detect early infection before seroconversion.')],
 'HCV exposure management differs from HBV and HIV', '**No HCV vaccine or recommended routine drug PEP is available.**',['Follow the source-risk testing pathway.','HCV RNA at about 3–6 weeks is part of indicated occupational follow-up.'], '**Link detected infection to prompt treatment assessment.**',['Later antibody follow-up may also be needed.','Do not confuse a baseline negative antibody with exclusion of the recent event.'],[['HCV PEP','Not routinely recommended'],['Early detection','RNA follow-up'],['If infected','Link to DAA treatment']],[HC])

if __name__=='__main__':print('Exposure prevention: '+str(len(rows))+' questions drafted')
